def validar_idade(idade):
    if idade < 0:
        raise ValueError("A idade não pode ser negativa!")
    return True

def sacar(saldo, valor):
    if valor > saldo:
        raise ValueError("Saldo insuficiente!")
    return saldo - valor

try:
    sacar(50, 100)
except ValueError as err:
    print(f"Capturado: {err}")
